import{af as e,z as t,J as a,ab as i}from"./chunks/framework.pGEaBvn1.js";const g=JSON.parse('{"title":"Why are there two location points?","description":"","frontmatter":{"sidebar":false,"editLink":false,"aside":false},"headers":[],"relativePath":"guides/two-tracking-locations.md","filePath":"guides/two-tracking-locations.md"}'),n={name:"guides/two-tracking-locations.md"};function c(d,o,r,s,h,l){return t(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793270749000"},[...o[0]||(o[0]=[i('<h1 id="why-are-there-two-location-points" tabindex="-1">Why are there two location points? <a class="header-anchor" href="#why-are-there-two-location-points" aria-label="Permalink to &quot;Why are there two location points?&quot;">​</a></h1><p><strong><code>Target Audience:</code></strong> First time users<br><strong><code>Difficulty:</code></strong> Easy<br><strong><code>Prerequisites:</code></strong> A Lightbug account and access to the mobile app</p><h2 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why?&quot;">​</a></h2><p>There will be two <a href="./../terminology/points">location points</a> if there has not been an accurate <code>location update</code> in more than <code>two days</code>. The most recent location is <em>not</em> always the most accurate. This accuracy depends on the last type of location update your device has emitted. <a href="./../terminology/positioning/gnss">GPS</a> updates are more accurate than <a href="./../terminology/positioning/wifi">WIFI</a> or <a href="./../devices/capabilities/ble-scanning">Bluetooth</a> updates.</p><p>Each device shows <code>two dots</code>, the <code>most recent</code> is shown here in <code>orange</code>, and the <code>older</code> one in <code>grey</code>:</p><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043268582248/original/XMGpwiriw5_B0jPA3F4aUMCIRLtB-vL0eQ.png?1634633576" alt="" width="200" tabindex="0"><figcaption></figcaption></figure><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h2><p><code>Tapping and holding</code> on the <code>orange dot</code> will display <code>basic information</code> about the location:</p><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043268582462/original/azCE3ud-C3MdKNLFd1F10xdpvnvzku7kJg.png?1634633597" alt="" width="200" tabindex="0"><figcaption></figcaption></figure><h2 id="more-information" tabindex="-1">More Information <a class="header-anchor" href="#more-information" aria-label="Permalink to &quot;More Information&quot;">​</a></h2><p><code>Tapping</code> on the <code>orange dot</code> displays several icons:</p><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043268582541/original/jG-Mhf5f3_syZGUxZZ42wBRwBeqOR2wO5A.png?1634633610" alt="" width="200" tabindex="0"><figcaption></figcaption></figure><p>You can tap on each icon to display <code>more in-depth information</code> about the location point:</p><ul><li>The <code>blue icon</code> displays information about the <code>Bluetooth beacon</code></li><li>The <code>yellow hourglass icon</code> displays the <code>age of the location point</code></li><li>The <code>yellow question mark icon</code> displays information about the <code>accuracy</code> of the location</li><li>The <code>cog icon</code> displays the <code>current device settings</code></li><li>The <code>red cross icon</code> closes the other icons.</li></ul><hr><p><code>Tapping</code> on the <code>grey dot</code> will pan the <code>older location</code> to the centre of the screen and display the <code>location information</code> at the <code>bottom of the screen</code> in black:</p><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043265375984/original/YQ7I5NVTBatZnY67KEkDeABQPjRoa9XA-w.png?1633685729" alt="" width="200" tabindex="0"><figcaption></figcaption></figure><p><code>Tapping</code> on the <code>show button</code> will <code>turn the location point red</code> and will pan it to the centre of the screen, displaying the <code>date and time</code> of the location point:</p><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043265375975/original/ZxdeJdnOcqxzvEeZtmv7gmO9-DJZIV1uog.png?1633685728" alt="" width="400" tabindex="0"><figcaption></figcaption></figure><blockquote><blockquote></blockquote></blockquote><figure><img src="https://s3.amazonaws.com/cdn.freshdesk.com/data/helpdesk/attachments/production/2043265375987/original/LkkSqZavvtutykmF6Hu6n85tO5dpiD-flg.png?1633685729" alt="" width="200" tabindex="0"><figcaption></figcaption></figure><p>If you have any additional questions about the two location points, don&#39;t be afraid to <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">reach out to us!</a></p>',22)])])}const f=e(n,[["render",c]]);export{g as __pageData,f as default};
